package com.kovian.finance.debt.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="debts")
public class Debt {
 @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Version @Column(nullable=false) Long version; @Column(name="owner_id",nullable=false) UUID ownerId; @Column(nullable=false) String name; @Enumerated(EnumType.STRING) @Column(name="debt_type",nullable=false) DebtType debtType; @Column(name="principal_amount",nullable=false,precision=19,scale=4) BigDecimal principalAmount; @Column(name="outstanding_amount",nullable=false,precision=19,scale=4) BigDecimal outstandingAmount; @Column(name="annual_interest_rate",precision=10,scale=6) BigDecimal annualInterestRate; @Column(name="start_date",nullable=false) LocalDate startDate; @Column(name="end_date") LocalDate endDate; @Column(name="total_installments",nullable=false) int totalInstallments; @Enumerated(EnumType.STRING) @Column(nullable=false) DebtStatus status=DebtStatus.ACTIVE; @Column(name="created_at",nullable=false) OffsetDateTime createdAt=OffsetDateTime.now();
 protected Debt(){} public Debt(UUID o,String n,DebtType t,BigDecimal principal,BigDecimal rate,LocalDate start,LocalDate end,int installments){if(o==null||n==null||n.isBlank()||principal==null||principal.signum()<=0||installments<1)throw new IllegalArgumentException("Invalid debt");ownerId=o;name=n.trim();debtType=t;principalAmount=principal;outstandingAmount=principal;annualInterestRate=rate;startDate=start;endDate=end;totalInstallments=installments;}
 public UUID getId(){return id;} public UUID getOwnerId(){return ownerId;} public String getName(){return name;} public DebtType getDebtType(){return debtType;} public BigDecimal getPrincipalAmount(){return principalAmount;} public BigDecimal getOutstandingAmount(){return outstandingAmount;} public BigDecimal getAnnualInterestRate(){return annualInterestRate;} public LocalDate getStartDate(){return startDate;} public LocalDate getEndDate(){return endDate;} public int getTotalInstallments(){return totalInstallments;} public DebtStatus getStatus(){return status;}
 public void pay(BigDecimal amount){if(amount==null||amount.signum()<=0||amount.compareTo(outstandingAmount)>0)throw new IllegalArgumentException("Invalid debt payment");outstandingAmount=outstandingAmount.subtract(amount);if(outstandingAmount.signum()==0)status=DebtStatus.PAID;}
}